/* Project library and user-selected history budget. Existing workspace keys stay compatible. */
function undoLimit(){return Math.max(25,Math.min(1000,Math.floor(Number(state.undoSteps)||25)))}
var Projects = {
  cover(b){const nodes=b.nodes.filter(n=>!['clock','soundscape','stamp'].includes(n.type)).slice(0,8);if(!nodes.length)return '<span class="project-cover empty-cover"><svg viewBox="0 0 260 118" aria-hidden="true"><rect x="93" y="23" width="74" height="77" rx="7" class="preview-paper"/><path d="M108 43h35m-35 10h23m7 15v16m-8-8h16" class="preview-line"/></svg><span class="project-cover-status">A FRESH CANVAS</span></span>';const minX=Math.min(...nodes.map(n=>n.x)),minY=Math.min(...nodes.map(n=>n.y)),maxX=Math.max(...nodes.map(n=>n.x+n.w)),maxY=Math.max(...nodes.map(n=>n.y+(n.h||170))),scale=Math.min(226/(maxX-minX||1),88/(maxY-minY||1)),position=n=>({x:17+(n.x-minX)*scale,y:15+(n.y-minY)*scale,w:Math.max(14,n.w*scale),h:Math.max(12,(n.h||170)*scale)}),map=new Map(nodes.map(n=>[n.id,position(n)]));let imageUsed=false;const edges=b.edges.filter(e=>map.has(e.from)&&map.has(e.to)).map(e=>{const a=map.get(e.from),c=map.get(e.to),x=a.x+a.w,y=a.y+a.h/2;return '<path d="M'+x+' '+y+'C'+(x+12)+' '+y+','+(c.x-12)+' '+(c.y+c.h/2)+','+c.x+' '+(c.y+c.h/2)+'" class="preview-wire"/>'}).join('');const cards=nodes.map(n=>{const p=map.get(n.id),paper=n.type==='sticky';let image='';if(!imageUsed&&['image','video'].includes(n.type)&&/^(data:image\/|https?:\/\/|\.\/)/.test(n.src||'')){image='<image href="'+escapeHTML(n.src)+'" x="'+(p.x+2)+'" y="'+(p.y+2)+'" width="'+(p.w-4)+'" height="'+Math.max(2,p.h-4)+'" preserveAspectRatio="xMidYMid slice"/>';imageUsed=true}return '<g><rect x="'+p.x+'" y="'+p.y+'" width="'+p.w+'" height="'+p.h+'" rx="'+(paper?1:3)+'" class="preview-paper '+(paper?'preview-sticky':'')+'"/>'+image+(!image?'<path d="M'+(p.x+5)+' '+(p.y+7)+'h'+Math.max(3,p.w-13)+'m-'+Math.max(3,p.w-13)+' 5h'+Math.max(3,p.w*.55)+'" class="preview-copy"/>':'')+'</g>'}).join('');return '<span class="project-cover"><svg viewBox="0 0 260 118" aria-hidden="true">'+edges+cards+'</svg><span class="project-cover-status">'+(b.id===state.activeBoard?'CURRENT PROJECT':'CREATIVE PROJECT')+'</span></span>';},
  open() {
    CanvasEditor.finish();if(tool!=='select')setTool('select');
    showModal(`<div class="modal-header"><div><div class="eyebrow">YOUR CREATIVE SPACE</div><h2 id="modalTitle">Your projects.</h2><p>Everything saves automatically. Pick up where you left off.</p></div>${closeButton()}</div><div class="project-library-bar"><label class="project-search">${icon('search')}<input id="projectSearch" aria-label="Find a project" placeholder="Find a project…"></label><button class="primary-btn" id="libraryNew">${icon('plus')}New project</button></div><div class="project-grid" id="projectGrid"></div>`,true);
    $('#modal').classList.add('projects-modal');const draw=()=>{const query=$('#projectSearch').value.trim().toLowerCase(),boards=state.boards.filter(b=>b.title.toLowerCase().includes(query));$('#projectGrid').innerHTML=boards.map(b=>`<article class="project-tile ${b.id===state.activeBoard?'current':''}"><button class="project-open" data-libboard="${escapeHTML(b.id)}" aria-label="Open ${escapeHTML(b.title)}">${this.cover(b)}<strong>${escapeHTML(b.title)}</strong><small>${icon('board')}${b.nodes.length} cards<span>·</span>${icon('pen')}${b.strokes.length} drawings</small></button><button class="icon-btn project-options" data-project-options="${escapeHTML(b.id)}" aria-label="Options for ${escapeHTML(b.title)}">${icon('more')}</button></article>`).join('')||'<div class="project-empty">No projects match that name.</div>';$$('[data-libboard]').forEach(b=>b.onclick=()=>{closeModal();openBoard(b.dataset.libboard)});$$('[data-project-options]').forEach(b=>b.onclick=e=>this.options(e,b.dataset.projectOptions));};
    $('#projectSearch').oninput=draw;$('#libraryNew').onclick=createBoard;draw();
  },
  options(e,id=board().id) { context(e,[['board','View projects',()=>this.open()],['plus','New project',createBoard],['text','Rename project',()=>renameBoard(id)],['download','Export workspace backup',exportBackup],['trash','Delete project',()=>{closeModal();deleteBoard(id)},true]]); },
  historySettings() {
    $('#modal').classList.remove('projects-modal');$('#modal .modal-header').insertAdjacentHTML('afterend',`<div class="settings-row"><div><strong>Undo history</strong><p>25 steps by default. More steps use more RAM.<br><span id="historyMemoryEstimate"></span></p></div><label class="history-steps"><input id="undoSteps" type="number" min="25" max="1000" step="1" value="${undoLimit()}" aria-label="Undo history steps"><span>steps</span></label></div>`);
    const estimate=()=>{const steps=undoLimit(),mb=JSON.stringify(state).length*2*steps/1024/1024;$('#historyMemoryEstimate').textContent='About '+(mb<1?'< 1':Math.round(mb))+' MB at the current workspace size.';};
    const apply=()=>{state.undoSteps=Math.max(25,Math.min(1000,Math.floor(+$('#undoSteps').value||25)));history.splice(0,Math.max(0,history.length-state.undoSteps));future.splice(0,Math.max(0,future.length-state.undoSteps));save();updateHistory();estimate()};$('#undoSteps').oninput=()=>{if(+$('#undoSteps').value>=25)apply()};$('#undoSteps').onchange=()=>{apply();$('#undoSteps').value=undoLimit()};estimate();
  }
};
